def apply(path,notes):
    L=open(path,encoding='utf8').read().split('\n'); done=[]
    for i,l in enumerate(L):
        m=re.match(r'\| (TC-[A-Z0-9-]+) \| LT \|',l)
        if m and m.group(1) in notes:
            L[i]=f"| {m.group(1)} | P | {notes[m.group(1)]} |"; done.append(m.group(1))
    open(path,'w',encoding='utf8').write('\n'.join(L)); return done
